pub trait OrderStore { fn save(&mut self, o: &Order) -> Result<(), StoreError>; }

// DIP by generic injection, monomorphised: no vtable
pub struct Publisher<S: OrderStore> { store: S }

// dynamic dispatch when the store is chosen at run time
pub fn publish(store: &mut dyn OrderStore, order: &Order) { store.save(order).unwrap(); }
